311	template <pipe_t SrcPipe, pipe_t DstPipe>
312	class EventIdCounter {
313	public:
314	    PTO_INTERNAL static event_t GetNextId()
315	    {
316	        event_t id = NextId();
317	#if defined(__CPU_SIM) || defined(__COSTMODEL)
318	        PTO_CPU_ASSERT(
319	            !(OccupiedMask() & (1u << static_cast<uint8_t>(id))), "Event ID still occupied - likely missing Wait()");
320	        OccupiedMask() |= (1u << static_cast<uint8_t>(id));
321	#endif
322	        NextId() = (event_t)(((uint8_t)NextId() + 1) % EVENT_ID_MAX);
323	        return id;
324	    }
325	    PTO_INTERNAL static void Reset()
326	    {
327	        NextId() = EVENT_ID0;
328	#if defined(__CPU_SIM) || defined(__COSTMODEL)
329	        OccupiedMask() = 0;
330	#endif
331	    }
332	    PTO_INTERNAL static event_t PeekNextId() { return NextId(); }
333	#if defined(__CPU_SIM) || defined(__COSTMODEL)
334	    PTO_INTERNAL static void MarkFree(event_t id) { OccupiedMask() &= ~(1u << static_cast<uint8_t>(id)); }
335	#endif
336	
337	private:
338	    static event_t& NextId()
339	    {
340	        static event_t id = EVENT_ID0;
341	        return id;
342	    }
343	#if defined(__CPU_SIM) || defined(__COSTMODEL)
344	    static uint8_t& OccupiedMask()
345	    {
346	        static uint8_t mask = 0;
347	        return mask;
348	    }
349	#endif
350	};
