379	// CRTP base class for platform-specific Event implementations.
380	// Derived must provide:
381	//   template <Op op> static constexpr pipe_t GetPipeByOp()
382	//   static constexpr bool IsCrossCore
383	//   template <uint8_t CrossCoreId> PTO_INTERNAL Derived& WaitImpl()
384	//   template <uint8_t CrossCoreId> PTO_INTERNAL Derived& InitImpl()
385	//   PTO_INTERNAL Derived& InitAddrImpl(uint64_t fftsAddr)
386	template <typename Derived, Op SrcOp, Op DstOp, bool AutoToken = true, event_t EventID = EVENT_ID0>
387	struct EventBase : EventBaseTag {
388	#ifndef __PTO_AUTO__
389	    static constexpr Op srcOp = SrcOp;
390	    static constexpr Op dstOp = DstOp;
391	    static constexpr pipe_t srcPipe = Derived::template GetPipeByOp<SrcOp>();
392	    static constexpr pipe_t dstPipe = Derived::template GetPipeByOp<DstOp>();
393	    static constexpr bool isSamePipe = (srcPipe == dstPipe);
394	
395	#ifdef PTO_FLAG_TEST
396	    CceEventIdType token = {};
397	#else
398	    const event_t token = AutoToken ? EventIdCounter<srcPipe, dstPipe>::GetNextId() : EventID;
399	#endif
400	#endif
401	
402	    PTO_INTERNAL Derived& InitAddr(uint64_t fftsAddr) { return self().InitAddrImpl(fftsAddr); }
403	
404	    template <uint8_t CrossCoreId = 0xff>
405	    PTO_INTERNAL Derived& Wait()
406	    {
407	#ifndef __PTO_AUTO__
408	        return self().template WaitImpl<CrossCoreId>();
409	#else
410	        return self();
411	#endif
412	    }
413	
414	    template <uint8_t CrossCoreId = 0xff>
415	    PTO_INTERNAL Derived& Init()
416	    {
417	#ifndef __PTO_AUTO__
418	        return self().template InitImpl<CrossCoreId>();
419	#else
420	        return self();
421	#endif
422	    }
423	
424	    template <uint8_t CrossCoreId = 0xff>
425	    PTO_INTERNAL Derived& Record()
426	    {
427	        return Init<CrossCoreId>();
428	    }
